TEST_F(HixlUTest, TestHixl) {
  llm::AutoCommResRuntimeMock::SetDevice(0);
  Hixl engine1;
  std::map<AscendString, AscendString> options1;
  options1[OPTION_RDMA_TRAFFIC_CLASS] = "4";
  options1[OPTION_RDMA_SERVICE_LEVEL] = "1";
  EXPECT_EQ(engine1.Initialize("127.0.0.1", options1), SUCCESS);

  llm::AutoCommResRuntimeMock::SetDevice(1);
  Hixl engine2;
  std::map<AscendString, AscendString> options2;
  EXPECT_EQ(engine2.Initialize("127.0.0.1:26201", options2), SUCCESS);

  int32_t src = 1;
  MemHandle handle1 = nullptr;
  RegisterInt32Mem(engine1, &src, handle1);

  int32_t dst = 2;
  MemHandle handle2 = nullptr;
  RegisterInt32Mem(engine2, &dst, handle2);

  EXPECT_EQ(engine1.Connect("127.0.0.1:26201"), SUCCESS);
  TransferOpDesc desc{reinterpret_cast<uintptr_t>(&src), reinterpret_cast<uintptr_t>(&dst), sizeof(int32_t)};
  EXPECT_EQ(engine1.TransferSync("127.0.0.1:26201", READ, {desc}), SUCCESS);
  EXPECT_EQ(src, 2);
  src = 1;
  EXPECT_EQ(engine1.TransferSync("127.0.0.1:26201", WRITE, {desc}), SUCCESS);
  EXPECT_EQ(dst, 1);
  EXPECT_EQ(engine1.Disconnect("127.0.0.1:26201"), SUCCESS);

  EXPECT_EQ(engine1.DeregisterMem(handle1), SUCCESS);
  EXPECT_EQ(engine2.DeregisterMem(handle2), SUCCESS);
  engine1.Finalize();
  engine2.Finalize();
}

TEST_F(HccnConfTest, TestGetDeviceIpFromHccnConf) {
  std::string device_ip = "";
  EXPECT_EQ(hixl::GetDeviceIp(0, device_ip), hixl::SUCCESS);
  EXPECT_EQ(device_ip, "1.1.1.0");
}

TEST_F(HccnToolTest, TestGetDeviceIpFromHccnToolWhenHccnConfMissing) {
  std::string device_ip = "";
  EXPECT_EQ(hixl::GetDeviceIp(0, device_ip), hixl::SUCCESS);
  EXPECT_EQ(device_ip, "1.1.1.0");
}

TEST_F(HccnGetOutputTest, TestGetDeviceIpEmptyWhenHccnConfAndToolUnavailable) {
  std::string device_ip = "";
  EXPECT_EQ(hixl::GetDeviceIp(0, device_ip), hixl::SUCCESS);
  EXPECT_TRUE(device_ip.empty());
}

TEST_F(HixlUTest, TestHixlInitFailed) {
  Hixl engine;
  std::map<AscendString, AscendString> options;
  // invalid ip
  EXPECT_EQ(engine.Initialize("ad.0.0.1:26200", options), PARAM_INVALID);
}

TEST_F(HixlUTest, TestInitializeRollsBackEngineWhenConnectPoolInitializationFails) {
  llm::AutoCommResRuntimeMock::SetDevice(0);
  Hixl engine;
  std::map<AscendString, AscendString> options = {
      {OPTION_GLOBAL_RESOURCE_CONFIG, R"({"connect_pool.thread_num":"0"})"}};

  EXPECT_EQ(engine.Initialize("127.0.0.1:26200", options), PARAM_INVALID);

  options.clear();
  EXPECT_EQ(engine.Initialize("127.0.0.1:26200", options), SUCCESS);
  EXPECT_EQ(engine.ConnectAsync("127.0.0.1:26201", 1), SUCCESS);
  engine.Finalize();
}

TEST_F(HixlUTest, TestConnectNotListenFailed) {
  Hixl engine;
  std::map<AscendString, AscendString> options;
  EXPECT_EQ(engine.Initialize("127.0.0.1:26200", options), SUCCESS);
  // not listen
  EXPECT_EQ(engine.Connect("127.0.0.1:26201"), FAILED);
}

TEST_F(HixlUTest, TestAlreadyConnectedFailed) {
  llm::AutoCommResRuntimeMock::SetDevice(0);
  Hixl engine1;
  std::map<AscendString, AscendString> options1;
  EXPECT_EQ(engine1.Initialize("127.0.0.1", options1), SUCCESS);

  llm::AutoCommResRuntimeMock::SetDevice(1);

